input.newString:
import { revalidatePath } from 'next/cache';

// Mock database for user preferences
const userPreferences = {
  notificationsEnabled: false
};

// Server Action to toggle notification preference
async function toggleNotificationPreference() {
  'use server';

  // Toggle the current preference
  userPreferences.notificationsEnabled = !userPreferences.notificationsEnabled;

  // Revalidate the current path to refresh the page
  revalidatePath('/');

  return { success: true, notificationsEnabled: userPreferences.notificationsEnabled };
}

export default function Home() {
  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <div>
          <label htmlFor="notifications">Enable Notifications</label>
          <input 
            type="checkbox" 
            id="notifications"
            name="notifications"
            checked={userPreferences.notificationsEnabled}
            onChange={() => {}}
          />
        </div>
        <button type="submit">Save Preference</button>
      </form>
      <p>Current status: {userPreferences.notificationsEnabled ? 'ON' : 'OFF'}</p>
    </main>
  );
}

